window.AUTH=window.AUTH||{};window.AUTH["24-656"]={"d":"24-656","id":"2024/24-656","n":"TikTok, Inc. v. Garland","briefs":[{"k":"petitioner","label":"Brief of petitioners TikTok Inc. and ByteDance Ltd.","date":"2024-12-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-656/336136/20241227160309446_24-656%20ts.pdf","side":"pet","n":45},{"k":"petitioner","label":"Brief of petitioners Brian Firebaugh, et al.","date":"2024-12-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-656/336134/20241227155801895_Firebaugh%20v.%20Garland%20--%20Merits%20Brief%20for%20Petitioners.pdf","side":"pet","n":60},{"k":"respondent","label":"Brief of respondent Merrick B. Garland, Attorney General","date":"2024-12-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-656/336144/20241227161148472_24-656tsGovt_final.pdf","side":"res","n":58},{"k":"reply","label":"Reply of petitioners TikTok Inc. and ByteDance Ltd.","date":"2025-01-03","url":"https://www.supremecourt.gov/DocketPDF/24/24-656/336542/20250103152311278_24-656%20rb.pdf","side":"pet","n":29},{"k":"reply","label":"Reply of petitioners Brian Firebaugh, et al.","date":"2025-01-03","url":"https://www.supremecourt.gov/DocketPDF/24/24-656/336546/20250103152823511_Firebaugh%20v.%20Garland%20--%20Reply%20Merits%20Brief.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r07_k536.pdf","tr":true,"items":[{"t":"case","label":"Agency for Int’l Dev. v. All. for Open Soc’y Int’l, Inc.","cite":"591 U.S. 430","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/430/","sc":1,"op":1,"sum":"Noting that American speakers “are free to choose whether to affiliate with foreign organizations”.","sumSrc":"brief:0","by":{"0":"22, 23, 27, 43","1":"22","2":"19-21","3":"5, 8"}},{"t":"case","label":"Arcara v. Cloud Books, Inc.","cite":"478 U.S. 697","y":1986,"id":"1985/85-437","sc":1,"op":3,"ar":5,"sum":"The First Amendment does not bar enforcement of the closure statute against respondents' bookstore. United States v. O'Brien, supra, has no relevance to a statute directed at imposing sanctions on nonexpressive activity, and the sexual activities carried on in this case manifest absolutely no element of protected expression. The closure statute is directed at unlawful conduct having nothing to do with books or other …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","2":"22, 23","3":"7","4":"6"}},{"t":"case","label":"Arizona Free Enter. Club’s Freedom Club PAC v. Bennett","cite":"564 U.S. 721","y":2011,"id":"2010/10-238","sc":1,"sum":"The Court held that the Arizona campaign finance law linking public financing for candidates to the amount spent by their opponents violated the First Amendment's protection of political speech.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Ashcroft v. ACLU","cite":"542 U.S. 656","y":2004,"id":"2003/03-218","sc":1,"sum":"In an interesting 5-to-4 vote, with Justices Kennedy, Stevens, Souter, Thomas and Ginsburg on one side and Chief Justice Rehnquist and Justices Scalia, Breyer and O'Connor on the other, the Court found that Congress had not yet met its burden to show that the COPA requirements were more effective than other methods of preventing minors.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Barr v. Am. Ass’n of Pol. Consultants, Inc.","cite":"591 U.S. 610","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/610/","sc":1,"sum":"Noting that American speakers “are free to choose whether to affiliate with foreign organizations”.","sumSrc":"brief:0","by":{"0":"32","1":"26"}},{"t":"case","label":"Boy Scouts of Am. v. Dale","cite":"530 U.S. 640","y":2000,"id":"1999/99-699","sc":1,"sum":"The Court held that the Boy Scouts of America banning openly homosexual members was constitutional under the First Amendment.","sumSrc":"Oyez","by":{"0":"26, 29","3":"11"}},{"t":"case","label":"Brandenburg v. Ohio","cite":"395 U.S. 444","y":1969,"id":"1968/492","sc":1,"sum":"The Court held that a Ku Klux Klan's First Amendment rights were violated by an Ohio criminal syndicalism law.","sumSrc":"Oyez","by":{"0":"40","1":"30, 31, 40"}},{"t":"case","label":"Brown v. Ent. Merchants Ass’n","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"op":1,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"0":"22, 31, 32, 36, 41, 42, 49","1":"2, 16, 30, 32, 34, 49, 51","2":"32","3":"7, 17"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Burson v. Freeman","cite":"504 U.S. 191","y":1992,"id":"1991/90-1056","sc":1,"sum":"After subjecting Tennessee's statute to exacting scrutiny, since it constituted a facial content-based restriction on political speech in a public forum, the Court held that the statute was narrowly drafted to serve a compelling state interest. By creating a safe zone around polling sites, the statute served the state's interest in protecting its citizen's right to vote freely and effectively.","sumSrc":"Oyez","by":{"0":"33","2":"44","4":"9"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"0":"40, 54"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"op":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"22, 39, 54"}},{"t":"case","label":"City of Austin v. Reagan Nat'l Advert. of Austin, LLC","cite":"596 U.S. 61","y":2022,"id":"2021/20-1029","sc":1,"ar":1,"sum":"The distinction between on-premises signs and off-premises signs in the City of Austin’s sign code is facially content neutral under the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32","2":"25"}},{"t":"case","label":"Holder v. Humanitarian L. Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"op":2,"ar":2,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"26, 33, 34, 38, 49, 51","1":"17, 42, 43, 46","2":"38, 42, 43, 46, 47","3":"10","4":"9, 12, 13"}},{"t":"case","label":"Kennedy v. Bremerton Sch. Dist.","cite":"597 U.S. 507","y":2022,"id":"2021/21-418","sc":1,"sum":"The Free Exercise and Free Speech Clauses of the First Amendment protect an individual engaging in a personal religious observance from government reprisal; the Constitution neither mandates nor permits the government to suppress such religious expression.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"31"}},{"t":"case","label":"Lamont v. Postmaster Gen.","cite":"381 U.S. 301","y":1965,"id":"1964/491","sc":1,"ar":8,"sum":"The Act as construed and applied is unconstitutional since it impos& on the addressee an affirmative obligation which amounts tou an unconstitutional limitation of his rights under the First Amendment. Pp.:305-307. 229 F. Supp. 913, reversed; 236 F. Supp. 405, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 37","1":"13, 16, 23, 37-38, 41","2":"47, 48","3":"16","4":"4, 14"}},{"t":"case","label":"McCullen v. Coakley","cite":"573 U.S. 464","y":2014,"id":"2013/12-1168","sc":1,"op":1,"sum":"The Court ruled that the Massachusetts legislature violated the freedom of speech protections of the First Amendment when it created a 35-foot buffer around the entrances, exits and driveways of abortion clinics where political activity was prohibited.","sumSrc":"Oyez","by":{"0":"32, 45–47","3":"14"}},{"t":"case","label":"Meese v. Keene","cite":"481 U.S. 465","y":1987,"id":"1986/85-1180","sc":1,"sum":"The Foreign Agents Registration Act of 1938 (Act) requires registration, reporting, and disclosure by persons engaging in propaganda on behalf of foreign powers. The Act uses the term \"political propaganda\" to identify those expressive materials subject to its requirements, and defines the term as, inter alia, any communication intended to influence the United States' foreign policies. Appellee, a member of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 39","1":"16, 38","4":"14, 16-17"}},{"t":"case","label":"Minneapolis Star & Tribune Co. v. Minn. Comm’r of Rev.","cite":"460 U.S. 575","y":1983,"id":"1982/81-1839","sc":1,"op":2,"sum":"The Court held that while the First Amendment did not prohibit all regulation of the press, Minnesota had \"created a special tax that applie[d] only to certain publications protected by the First Amendment.\" Noting that there was \"substantial evidence that differential taxation of the press would have troubled the Framers of the First Amendment,\" the Court held that when states single out the press \"the threat of burdensome taxes becomes acute.\" The Court concluded that \"recognizing a power in the State not only to single out the press but also to tailor the tax so that it singles out a few members of the press presents such a potential for abuse that no interest suggested by Minnesota can justify the scheme.\".","sumSrc":"Oyez","by":{"0":"27","1":"18, 50","3":"7","4":"21"}},{"t":"case","label":"Moody v. NetChoice","cite":"603 U.S. 707","y":2024,"id":"2023/22-277","sc":1,"op":2,"sum":"The judgments are vacated, and the cases are remanded, because neither the Eleventh Circuit nor the Fifth Circuit conducted a proper analysis of the facial First Amendment challenges to the Florida and Texas laws regulating large internet platforms.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 20–23, 26, 35–37","1":"2, 13, 22, 24, 32-33, 42","2":"20, 48","3":"5, 6","4":"5, 11, 18, 23"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Mt. Healthy City Sch. Dist. Bd. of Educ. v. Doyle","cite":"429 U.S. 274","y":1977,"id":"1976/75-1278","sc":1,"ar":3,"sum":"Writing for a unanimous Court, Justice Rehnquist held that the school district was not entitled to sovereign immunity, which generally extended to the states themselves and to state officials in their official capacities. He reasoned that the board was more akin to a municipal corporation, given its independent power to issue bonds and levy taxes.","sumSrc":"Oyez","by":{"0":"41","1":"48","2":"35, 36","3":"18, 19","4":"18"}},{"t":"case","label":"Nat’l Inst. of Fam. & Life Advocs. v. Becerra","cite":"585 U.S. 755","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/755/","sc":1,"by":{"0":"32, 42, 43"}},{"t":"case","label":"News Am. Pub., Inc. v. FCC","cite":"844 F.2d 800","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/844/800/","ar":3,"by":{"0":"54"}},{"t":"case","label":"Reed v. Town of Gilbert","cite":"576 U.S. 155","y":2015,"id":"2014/13-502","sc":1,"op":3,"sum":"Explaining that some facial distinctions defne regulated speech by subject matter, others by the speech's function or purpose.","sumSrc":"opinion","by":{"0":"25–27, 31, 32, 54","1":"24, 26","2":"25","3":"11","4":"9, 11"}},{"t":"case","label":"Reno v. ACLU","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"sum":"The Court ruled that certain provisions of the Communications Decency Act concerning \"indecent\" behavior were unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"30, 38, 39, 44","1":"32, 42","4":"15"}},{"t":"case","label":"Rumsfeld v. Forum for Acad. & Institutional Rts., Inc.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"op":2,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"0":"23","1":"21","2":"24"}},{"t":"case","label":"Sable Commc’ns of Cal., Inc. v. FCC","cite":"492 U.S. 115","y":1989,"id":"1988/88-515","sc":1,"sum":"Since the First Amendment does not protect obscene speech, as the Court found in Paris Adult Theater I v. Slaton (1973), the ban on obscene speech was legitimate. However, sexual expression that is simply indecent is protected. Thus, banning adult access to indecent messages \"far exceeds that which is necessary\" to shield minors from dial-a-porn services.","sumSrc":"Oyez","by":{"0":"45, 46","1":"53","2":"36"}},{"t":"case","label":"Shaw v. Hunt","cite":"517 U.S. 899","y":1996,"id":"1995/94-923","sc":1,"sum":"In a 5-to-4 opinion by Chief Justice Rehnquist, the Court first confronted the threshold question of \"standing.\" It held that some of the appellants lacked proper standing to challenge the redistricting plan. Only those voters who resided in a congressional district alleged to have been created by racial gerrymandering had proper standing to challenge the constitutionality of that district's creation.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Simon & Schuster, Inc. v. Members of N.Y. State Crime Victims Bd.","cite":"502 U.S. 105","y":1991,"id":"1991/90-1059","sc":1,"ar":2,"sum":"The Court concluded that \"New York has singled out speech on a particular subject for a financial burden that it places on no other speech and no other income.\" This discrimination could only be justified if the state could show \"that its regulation is necessary to serve a compelling state interest and is narrowly drawn to achieve that end\" (Arkansas Writers' Project, Inc. v. Ragland, 481 U.S. 221, 231 (1987)).","sumSrc":"Oyez","by":{"0":"24–26"}},{"t":"case","label":"Sorrell v. IMS Health Inc.","cite":"564 U.S. 552","y":2011,"id":"2010/10-779","sc":1,"ar":2,"sum":"The Court held that a Vermont statute banning the sale, transmission or use of prescription drug user data violated protected speech of the pharmaceutical research companies, manufacturers and others who use that data.","sumSrc":"Oyez","by":{"0":"28","1":"31","2":"25","3":"11","4":"2"}},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"op":5,"sum":"Holding noise control and sound quality justifcations behind city sound amplifcation guideline were content neutral.","sumSrc":"opinion","by":{"0":"26","1":"44","3":"10","4":"10"}},{"t":"case","label":"Thompson v. W. States Med. Ctr.","cite":"535 U.S. 357","y":2002,"id":"2001/01-344","sc":1,"sum":"The Court held that the FDAMA's provisions amounted to unconstitutional restrictions on commercial speech.","sumSrc":"Oyez","by":{"0":"45","3":"13"}},{"t":"case","label":"Turner Broad. Sys., Inc. v. FCC","cite":"512 U.S. 622","y":1994,"id":"1993/93-44","sc":1,"op":7,"sum":"The Court held that the must-carry provisions were content neutral, thus not a violation of the First Amendment. The rules were not determined by the programming content, but by broadcast method. The rules promote fair competition in television programming.","sumSrc":"Oyez","by":{"0":"30, 47","2":"25, 46","4":"15"}},{"t":"case","label":"Turner Broad. Sys., Inc. v. FCC","cite":"520 U.S. 180","y":1997,"id":"1996/95-992","sc":1,"op":4,"sum":"In a 5-to-4 decision, the Court held that Congress \"has an independent interest in preserving a multiplicity of broadcasters.\" The outcome supported Congress's right to judge what approach would best insure a competitive communications marketplace.","sumSrc":"Oyez","by":{"0":"35","2":"28"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"0":"28","2":"24, 28, 36","3":"10, 18","4":"6"}},{"t":"case","label":"United States v. Playboy Ent. Grp.","cite":"529 U.S. 803","y":2000,"id":"1999/98-1682","sc":1,"ar":1,"sum":"The Court held that because the Federal Government failed to show that section 505 was the least restrictive means to further its interests, requiring cable television operators to fully scramble or limit time when sexually-oriented programming was transmitted violated the First Amendment's free speech guarantee.","sumSrc":"Oyez","by":{"0":"25, 27, 30, 32, 44, 47, 54","1":"52","3":"7, 14"}},{"t":"case","label":"Va. Pharmacy Bd. v. Va. Consumer Council","cite":"425 U.S. 748","y":1976,"id":"1975/74-895","sc":1,"sum":"In a 7-to-1 opinion, the Court held that the First Amendment protects willing speakers and willing listeners equally. The Court noted that in cases of commercial speech, such as price advertising, freedom of speech protections apply just as they would to noncommercial speech. Even speech that is sold for profit, or involves financial solicitations, is protected.","sumSrc":"Oyez","by":{"0":"25, 37","1":"31, 44","4":"16"}},{"t":"case","label":"Williams-Yulee v. Florida Bar","cite":"575 U.S. 433","y":2015,"id":"2014/13-1499","sc":1,"op":1,"sum":"The Court held that a rule prohibiting judicial candidates from personally soliciting campaign funds does not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"33, 34, 42–44","1":"49","2":"28, 33, 43"}},{"t":"case","label":"Zauderer v. Off. of Disciplinary Couns. of Sup. Ct. of Ohio","cite":"471 U.S. 626","y":1985,"id":"1984/83-2166","sc":1,"ar":1,"sum":"The reprimand is sustainable to the extent that it is based on appellant's advertisement involving his terms of representation in drunken driving cases and on the omission of information regarding his contingent-fee arrangements in his Dalkon Shield advertisement. But insofar as the reprimand is based on appellant's use of an illustration in his advertisement and his offer of legal advice, the reprimand violated his …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","1":"52"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"40","2":"2, 11, 14, 16, 17, 19-28, 33, 35, 36, 40, 41, 44, 47, 48"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"22 U.S.C. § 611","url":"https://www.law.cornell.edu/uscode/text/22/611","subs":["(j)(1964)"],"stext":{"head":"§611. Definitions","paras":[[0,"As used in and for the purposes of this subchapter—"],[0,"(a) The term \"person\" includes an individual, partnership, association, corporation, organization, or any other combination of individuals;"],[0,"(b) The term \"foreign principal\" includes—"],[1,"(1) a government of a foreign country and a foreign political party;"],[1,"(2) a person outside of the United States, unless it is established that such person is an individual and a citizen of and domiciled within the United States, or that such person is not an individual and is organized under or created by the laws of the United States or of any State or other place subject to the jurisdiction of the United States and has its principal place of business within the United States; and"],[1,"(3) a partnership, association, corporation, organization, or other combination of persons organized under the laws of or having its principal place of business in a foreign country."],[0,"(c) Expect 1 as provided in subsection (d) of this section, the term \"agent of a foreign principal\" means—"],[1,"(1) any person who acts as an agent, representative, employee, or servant, or any person who acts in any other capacity at the order, request, or under the direction or control, of a foreign principal or of a person any of whose activities are directly or indirectly supervised, directed, controlled, financed, or subsidized in whole or in major part by a foreign principal, and who directly or through any other person—"],[2,"(i) engages within the United States in political activities for or in the interests of such foreign principal;"],[2,"(ii) acts within the United States as a public relations counsel, publicity agent, information-service employee or political consultant for or in the interests of such foreign principal;"],[2,"(iii) within the United States solicits, collects, disburses, or dispenses contributions, loans, money, or other things of value for or in the interest of such foreign principal; or"],[2,"(iv) within the United States represents the interests of such foreign principal before any agency or official of the Government of the United States; and"],[1,"(2) any person who agrees, consents, assumes or purports to act as, or who is or holds himself out to be, whether or not pursuant to contractual relationship, an agent of a foreign principal as defined in clause (1) of this subsection."],[0,"(d) The term \"agent of a foreign principal\" does not include any news or press service or association organized under the laws of the United States or of any State or other place subject to the jurisdiction of the United States, or any newspaper, magazine, periodical, or other publication for which there is on file with the United States Postal Service information in compliance with section 3611 2 of title 39, published in the United States, solely by virtue of any bona fide news or journalistic activities, including the solicitation or acceptance of advertisements, subscriptions, or other compensation therefor, so long as it is at least 80 per centum beneficially owned by, and its officers and directors, if any, are citizens of the United States, and such news or press service or association, newspaper, magazine, periodical, or other publication, is not owned, directed, supervised, controlled, subsidized, or financed, and none of its policies are determined by any foreign principal defined in subsection (b) of this section, or by any agent of a foreign principal required to register under this subchapter;"],[0,"(e) The term \"government of a foreign country\" includes any person or group of persons exercising sovereign de facto or de jure political jurisdiction over any country, other than the United States, or over any part of such country, and includes any subdivision of any such group and any group or agency to which such sovereign de facto or de jure authority or functions are directly or indirectly delegated. Such term shall include any faction or body of insurgents within a country assuming to exercise governmental authority whether such faction or body of insurgents has or has not been recognized by the United States;"],[0,"(f) The term \"foreign political party\" includes any organization or any other combination of individuals in a country other than the United States, or any unit or branch thereof, having for an aim or purpose, or which is engaged in any activity devoted in whole or in part to, the establishment, administration, control, or acquisition of administration or control, of a government of a foreign country or a subdivision thereof, or the furtherance or influencing of the political or public interests, policies, or relations of a government of a foreign country or a subdivision thereof;"],[0,"(g) The term \"public-relations counsel\" includes any person who engages directly or indirectly in informing, advising, or in any way representing a principal in any public relations matter pertaining to political or public interests, policies, or relations of such principal;"],[0,"(h) The term \"publicity agent\" includes any person who engages directly or indirectly in the publication or dissemination of oral, visual, graphic, written, or pictorial information or matter of any kind, including publication by means of advertising, books, periodicals, newspapers, lectures, broadcasts, motion pictures, or otherwise;"],[0,"(i) The term \"information-service employee\" includes any person who is engaged in furnishing, disseminating, or publishing accounts, descriptions, information, or data with respect to the political, industrial, employment, economic, social, cultural, or other benefits, advantages, facts, or conditions of any country other than the United States or of any government of a foreign country or of a foreign political party or of a partnership, association, corporation, organization, or other combination of individuals organized under the laws of, or having its principal place of business in, a foreign country;"],[0,"(j) Repealed. Pub. L. 104–65, §9(1)(A), Dec. 19, 1995, 109 Stat. 699."],[0,"(k) The term \"registration statement\" means the registration statement required to be filed with the Attorney General under section 612(a) of this title, and any supplements thereto required to be filed under section 612(b) of this title, and includes all documents and papers required to be filed therewith or amendatory thereof or supplemental thereto, whether attached thereto or incorporated therein by reference;"],[0,"(l) The term \"American republic\" includes any of the states which were signatory to the Final Act of the Second Meeting of the Ministers of Foreign Affairs of the American Republics at Habana, Cuba, July 30, 1940;"],[0,"(m) The term \"United States\", when used in a geographical sense, includes the several States, the District of Columbia, the Territories, the Canal Zone, the insular possessions, and all other places now or hereafter subject to the civil or military jurisdiction of the United States;"],[0,"(n) The term \"prints\" means newspapers and periodicals, books, pamphlets, sheet music, visiting cards, address cards, printing proofs, engravings, photographs, pictures, drawings, plans, maps, patterns to be cut out, catalogs, prospectuses, advertisements, and printed, engraved, lithographed, or autographed notices of various kinds, and, in general, all impressions or reproductions obtained on paper or other material assimilable to paper, on parchment or on cardboard, by means of printing, engraving, lithography, autography, or any other easily recognizable mechanical process, with the exception of the copying press, stamps with movable or immovable type, and the typewriter;"],[0,"(o) The term \"political activities\" means any activity that the person engaging in believes will, or that the person intends to, in any way influence any agency or official of the Government of the United States or any section of the public within the United States with reference to formulating, adopting, or changing the domestic or foreign policies of the United States or with reference to the political or public interests, policies, or relations of a government of a foreign country or a foreign political party;"],[0,"(p) The term \"political consultant\" means any person who engages in informing or advising any other person with reference to the domestic or foreign policies of the United States or the political or public interest, policies, or relations of a foreign country or of a foreign political party."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/611?type=usc&year=mostrecent&link-type=html"},"head":"§611. Definitions","tname":"Foreign Relations and Intercourse","by":{"0":"39–40","2":"39","4":"4"}},{"t":"law","label":"Pub. L. No. 118-50","url":"https://www.govinfo.gov/link/plaw/118/public/50","by":{"0":"12, 14, 46, 52, 46","1":"51","2":"2, 9","3":"20, 23","4":"3, 9, 21"}},{"t":"case","label":"Abrams v. United States","cite":"250 U.S. 616","y":1919,"id":"1900-1940/250us616","sc":1,"op":2,"ar":4,"sum":"The Court found that the Espionage Act did not violate the First Amendment if the speech incited resistance to war.","sumSrc":"Oyez","by":{"1":"40","4":"17"}},{"t":"case","label":"Alario v. Knudsen","cite":"704 F. Supp. 3d 1061","y":2023,"court":"D. Mont.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/704/1061/","by":{"1":"8"}},{"t":"case","label":"Am. Meat Inst. v. U.S. Dep’t of Agric.","cite":"760 F.3d 18","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/760/18/","by":{"1":"52"}},{"t":"case","label":"Americans for Prosperity Found. v. Bonta","cite":"594 U.S. 595","y":2021,"id":"2020/19-251","sc":1,"op":11,"ar":32,"sum":"The Ninth Circuit’s judgment, which vacated the District Court’s injunction of California’s compelled disclosure of Schedule Bs as not narrowly tailored to the State’s interest in investigating charitable misconduct, is reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21"}},{"t":"case","label":"Ark. Writers’ Project, Inc. v. Ragland","cite":"481 U.S. 221","y":1987,"id":"1986/85-1370","sc":1,"sum":"Arkansas imposes a tax on receipts from sales of tangible personal property, but exempts numerous items, including newspapers and \"religious, professional, trade, and sports journals and/or publications printed and published within this State\" (magazine exemption). Appellant publishes in Arkansas a general interest magazine that includes articles on a variety of subjects, including religion and sports. In 1984, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 50","4":"20-21"}},{"t":"case","label":"Ashcroft v. ACLU","cite":"535 U.S. 564","y":2002,"id":"2001/00-1293","sc":1,"sum":"The Court held that COPA's reliance on community standards to identify what material is harmful to minors does not by itself render the statute substantially overbroad for First Amendment purposes.","sumSrc":"Oyez","by":{"1":"16, 30"}},{"t":"case","label":"Bridges v. California","cite":"314 U.S. 252","y":1941,"id":"1940-1955/314us252","sc":1,"sum":"The Court reversed the Supreme Court of California and found the fines for contempt unconstitutional. Justice Hugo L. Black, writing for the majority, relied on the \"clear and present danger\" standard set forth in Schenk v. United States .","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"City of Ladue v. Gilleo","cite":"512 U.S. 43","y":1994,"id":"1993/92-1856","sc":1,"op":7,"sum":"Although acknowledging Ladue's police power to minimize visual clutter associated with signs, the Court ruled that the law \"almost completely foreclosed a venerable means of communication that is both unique and important.\" The Court held a \"special respect\" for an individual's right to convey messages from her home.","sumSrc":"Oyez","by":{"1":"21","4":"8"}},{"t":"case","label":"Craig v. Harney","cite":"331 U.S. 367","y":1947,"id":"scdb/1946-102","sc":1,"sum":"1. The publication in a newspaper of news articles, which unfairly reported events in a case pending in a state court, and an editorial, which vehemently attacked the trial judge (a layman elected for a short term) while a motion for a new trial was pending, did not, in the circumstances of this case, constitute a clear and present danger to the administration of justice; and the conviction of the newspapermen for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Dennis v. United States","cite":"341 U.S. 494","y":1951,"id":"1940-1955/341us494","sc":1,"sum":"The Court decided that the Smith Act, a federal law which made it a crime to advocate or organize for the purpose of overthrowing the government, did not violate the First Amendment of the Constitution.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Org.","cite":"597 U.S. 215","y":2022,"id":"2021/19-1392","sc":1,"sum":"The Constitution does not confer a right to abortion; Roe v. Wade, 410 U. S. 113, and Planned Parenthood of Southeastern Pa. v. Casey, 505 U. S. 833, are overruled; the authority to regulate abortion is returned to the people and their elected representatives.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"41"}},{"t":"case","label":"Gertz v. Robert Welch, Inc.","cite":"418 U.S. 323","y":1974,"id":"1973/72-617","sc":1,"sum":"Private individuals need only prove negligence to recover in defamation suits against news media","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Gitlow v. New York","cite":"268 U.S. 652","y":1925,"id":"1900-1940/268us652","sc":1,"sum":"The Court held that the First Amendment right to free speech is applicable against the states via the Fourteenth Amendment, but speech advocating the violent overthrow of government is not protected.","sumSrc":"Oyez","by":{"1":"40, 45"}},{"t":"case","label":"Houston Cmty. Coll. System v. Wilson","cite":"595 U.S. 468","y":2022,"id":"2021/20-804","sc":1,"sum":"Respondent Wilson does not possess an actionable First Amendment claim arising from his purely verbal censure by the Board of Trustees of the Houston Community College System.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Hurley v. Irish-American Gay, Lesbian & Bisexual Grp. of Boston","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"sum":"A unanimous court held that the State Court's ruling to require private citizens who organize a parade to include a group expressing a message that the organizers do not wish to convey violates the First Amendment by making private speech subordinate to the public accommodation requirement.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Iancu v. Brunetti","cite":"588 U.S. 388","y":2019,"id":"2018/18-302","sc":1,"sum":"The Lanham Act prohibition on the registration of “immoral” or “scandalous” trademarks infringes the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25"}},{"t":"case","label":"Joseph Burstyn, Inc. v. Wilson","cite":"343 U.S. 495","y":1952,"id":"scdb/1951-084","sc":1,"sum":"Provisions of the New York Education Law which forbid the commercial showing of any motion picture film without a license and authorize denial of a license on a censor's conclusion that a film is \"sacrilegious,\" held void as a prior restraint on freedom of, speech and of the press under the First Amendment, made applicable to the states by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Klein v. Facebook, Inc.","cite":"580 F. Supp. 3d 743","y":2022,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/580/743/","by":{"1":"8"}},{"t":"case","label":"Landmark Commc’ns, Inc. v. Virginia","cite":"435 U.S. 829","y":1978,"id":"1977/76-1450","sc":1,"sum":"The Court ruled 7-0 reversing the Supreme Court of Virginia. Chief Justice Warren E. Burger authored the majority opinion. Speaking for six members of the Court, Burger recognized the need for confidentiality in the Commission's proceedings. However, the disclosure of information from the Commission hearing by the Pilot served a public interest consistent with New York Times v. Sullivan.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Marland v. Trump","cite":"498 F. Supp. 3d 624","y":2020,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/498/624/","op":1,"by":{"1":"8, 37","2":"7"}},{"t":"case","label":"Martin v. City of Struthers","cite":"319 U.S. 141","y":1943,"id":"1940-1955/319us141","sc":1,"op":1,"sum":"The Court reversed the Supreme Court of Ohio and held Struthers' ordinance unconstitutional. In the majority opinion written by Justice Hugo L. Black, the Court acknowledged the city's interest in preventing crime and reducing nuisances. However, alternative solutions, such as trespassing laws, were also available that could achieve the city's purpose.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Miami Herald Publ’g Co. v. Tornillo","cite":"418 U.S. 241","y":1974,"id":"1973/73-797","sc":1,"sum":"The Court reversed the Supreme Court of Florida and held that Florida's \"right to reply\" statute violated the freedom of press found in the First Amendment. In an opinion written by Chief Justice Warren E. Burger, the Court recognized the risks posed to the \"true marketplace of ideas\" by media consolidation and barriers to entry in the newspaper industry.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"N.Y. Times Co. v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"N.Y. Times Co. v. United States","cite":"403 U.S. 713","y":1971,"id":"1970/1873","sc":1,"sum":"The Court found that the use of \"prior restraint\" by President Nixon on a New York Times article about activities in Vietnam was an unconstitutional violation of the First Amendment.","sumSrc":"Oyez","by":{"1":"43, 45"}},{"t":"case","label":"NAACP v. Patterson","cite":"357 U.S. 449","y":1958,"id":"1957/91","sc":1,"sum":"The Court ruled that Alabama's requirement for the NAACP to divulge the names and addresses of all of its members and agents in the state violated the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Noto v. United States","cite":"367 U.S. 290","y":1961,"id":"1960/9","sc":1,"sum":"The judgment is reversed, because the evidence was insufficient to prove that the Communist Party presently advocated forcible overthrow of the Government, not as an abstract doctrine, but by the use of language reasonably and ordinarily calculated to incite persons to action, immediately or in the future.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Packingham v. North Carolina","cite":"582 U.S. 98","y":2017,"id":"2016/15-1194","sc":1,"sum":"The Court determined that the North Carolina law prohibiting registered sex offenders from accessing various websites, where minors are known to be active and have accounts, regardless of whether or not the sex offender directly interacted with a minor violates the First Amendment.","sumSrc":"Oyez","by":{"1":"4, 15, 19-20, 24","4":"2, 8"}},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"op":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"1":"31","4":"7"}},{"t":"case","label":"Rosenberger v. Rector & Visitors of Univ. of Va.","cite":"515 U.S. 819","y":1995,"id":"1994/94-329","sc":1,"sum":"The Court, in a 5-to-4 opinion, held that the University's denial of funding to Rosenberger, due to the content of his message, imposed a financial burden on his speech and amounted to viewpoint discrimination. The Court noted that no matter how scarce University publication funding may be, if it chooses to promote speech at all, it must promote all forms of it equally.","sumSrc":"Oyez","by":{"1":"25, 26"}},{"t":"case","label":"Snyder v. Phelps","cite":"562 U.S. 443","y":2011,"id":"2010/09-751","sc":1,"sum":"The Court held that the Westboro Baptist Church was protected under the First Amendment while picketing a military funeral.","sumSrc":"Oyez","by":{"1":"44","4":"10"}},{"t":"case","label":"Stanley v. Georgia","cite":"394 U.S. 557","y":1969,"id":"1968/293","sc":1,"sum":"The Court held that the First and Fourteenth Amendments prohibited making private possession of obscene materials a crime. In his majority opinion, Justice Marshall noted that the rights to receive information and to personal privacy were fundamental to a free society.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"TikTok Inc. v. Trump","cite":"490 F. Supp. 3d 73","y":2020,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/490/73/","by":{"1":"37","2":"7"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Vidal v. Elster","cite":"602 U.S. 286","y":2024,"id":"2023/22-704","sc":1,"sum":"The Lanham Act’s names clause—which prohibits the registration of a mark that “[c]onsists of or comprises a name . . . identifying a particular living individual except by his written consent,” 15 U. S. C. §1052(c)—does not violate the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Viereck v. United States","cite":"318 U.S. 236","y":1943,"id":"scdb/1942-162","sc":1,"sum":"1. Where the charge of the trial court in a criminal prosecution for violation of the Act of June 8, 1938, as amended by the Act of August 7, 1939, authorized the jury to return a verdict of guilty if it found that the defendant had willfully failed to disclose activities which were wholly on his own behalf, the conviction can be sustained only if the failure to disclose such activities was a criminal offense, even …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Vill. of Arlington Heights v. Metro. Hous. Dev. Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"1":"48","2":"35, 36"}},{"t":"case","label":"W. Va. Bd. of Educ. v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"sum":"The Court found that a West Virginia statute requiring students and teachers say the Pledge of Allegiance, under threat of expulsion and delinquency charges, was unconstitutional.","sumSrc":"Oyez","by":{"1":"30, 44","4":"12"}},{"t":"case","label":"Whitney v. California","cite":"274 U.S. 357","y":1927,"id":"1900-1940/274us357","sc":1,"op":2,"ar":3,"sum":"The Court held that despite the First Amendment, a state can use its police power to punish speech that undermines the public welfare by inciting criminal activity, disturbing the peace, or advocating the violent overthrow of the government.","sumSrc":"Oyez","by":{"1":"4, 17, 39-41, 43, 45-46","4":"4, 12, 16"}},{"t":"usc","label":"50 U.S.C. § 1702","url":"https://www.law.cornell.edu/uscode/text/50/1702","subs":["(b)(3)"],"stext":{"head":"§1702. Presidential authorities","paras":[[0,"(a) In general"],[0,"(1) At the times and to the extent specified in section 1701 of this title, the President may, under such regulations as he may prescribe, by means of instructions, licenses, or otherwise—"],[1,"(A) investigate, regulate, or prohibit—"],[2,"(i) any transactions in foreign exchange,"],[2,"(ii) transfers of credit or payments between, by, through, or to any banking institution, to the extent that such transfers or payments involve any interest of any foreign country or a national thereof,"],[2,"(iii) the importing or exporting of currency or securities,"],[1,"by any person, or with respect to any property, subject to the jurisdiction of the United States;"],[1,"(B) investigate, block during the pendency of an investigation, regulate, direct and compel, nullify, void, prevent or prohibit, any acquisition, holding, withholding, use, transfer, withdrawal, transportation, importation or exportation of, or dealing in, or exercising any right, power, or privilege with respect to, or transactions involving, any property in which any foreign country or a national thereof has any interest by any person, or with respect to any property, subject to the jurisdiction of the United States; and.1"],[1,"(C) when the United States is engaged in armed hostilities or has been attacked by a foreign country or foreign nationals, confiscate any property, subject to the jurisdiction of the United States, of any foreign person, foreign organization, or foreign country that he determines has planned, authorized, aided, or engaged in such hostilities or attacks against the United States; and all right, title, and interest in any property so confiscated shall vest, when, as, and upon the terms directed by the President, in such agency or person as the President may designate from time to time, and upon such terms and conditions as the President may prescribe, such interest or property shall be held, used, administered, liquidated, sold, or otherwise dealt with in the interest of and for the benefit of the United States, and such designated agency or person may perform any and all acts incident to the accomplishment or furtherance of these purposes."],[0,"(2) In exercising the authorities granted by paragraph (1), the President may require any person to keep a full record of, and to furnish under oath, in the form of reports or otherwise, complete information relative to any act or transaction referred to in paragraph (1) either before, during, or after the completion thereof, or relative to any interest in foreign property, or relative to any property in which any foreign country or any national thereof has or has had any interest, or as may be otherwise necessary to enforce the provisions of such paragraph. In any case in which a report by a person could be required under this paragraph, the President may require the production of any books of account, records, contracts, letters, memoranda, or other papers, in the custody or control of such person."],[0,"(3) Compliance with any regulation, instruction, or direction issued under this chapter shall to the extent thereof be a full acquittance and discharge for all purposes of the obligation of the person making the same. No person shall be held liable in any court for or with respect to anything done or omitted in good faith in connection with the administration of, or pursuant to and in reliance on, this chapter, or any regulation, instruction, or direction issued under this chapter."],[0,"(b) Exceptions to grant of authority"],[0,"The authority granted to the President by this section does not include the authority to regulate or prohibit, directly or indirectly—"],[1,"(1) any postal, telegraphic, telephonic, or other personal communication, which does not involve a transfer of anything of value;"],[1,"(2) donations, by persons subject to the jurisdiction of the United States, of articles, such as food, clothing, and medicine, intended to be used to relieve human suffering, except to the extent that the President determines that such donations (A) would seriously impair his ability to deal with any national emergency declared under section 1701 of this title, (B) are in response to coercion against the proposed recipient or donor, or (C) would endanger Armed Forces of the United States which are engaged in hostilities or are in a situation where imminent involvement in hostilities is clearly indicated by the circumstances; or 2"],[1,"(3) the importation from any country, or the exportation to any country, whether commercial or otherwise, regardless of format or medium of transmission, of any information or informational materials, including but not limited to, publications, films, posters, phonograph records, photographs, microfilms, microfiche, tapes, compact disks, CD ROMs, artworks, and news wire feeds. The exports exempted from regulation or prohibition by this paragraph do not include those which are otherwise controlled for export under section 4604 3 of this title, or under section 4605 3 of this title to the extent that such controls promote the nonproliferation or antiterrorism policies of the United States, or with respect to which acts are prohibited by chapter 37 of title 18; or"],[1,"(4) any transactions ordinarily incident to travel to or from any country, including importation of accompanied baggage for personal use, maintenance within any country including payment of living expenses and acquisition of goods or services for personal use, and arrangement or facilitation of such travel including nonscheduled air, sea, or land voyages."],[0,"(c) Classified information"],[0,"In any judicial review of a determination made under this section, if the determination was based on classified information (as defined in section 1(a) of the Classified Information Procedures Act) such information may be submitted to the reviewing court ex parte and in camera. This subsection does not confer or imply any right to judicial review."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1702?type=usc&year=mostrecent&link-type=html"},"head":"§1702. Presidential authorities","tname":"War and National Defense","by":{"1":"37","4":"14"}},{"t":"case","label":"Barenblatt v. United States","cite":"360 U.S. 109","y":1959,"id":"1958/35","sc":1,"sum":"The divided Court found that the Committee's actions did not violate the First Amendment and, thus, upheld Barenblatt's conviction for contempt of Congress. Justice Harlan noted that the First Amendment does not protect a witness from all lines of questioning. As long as the Congressional inquiry is pursued to \"aid the legislative process\" and to protect important government interests, then it is legitimate.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"Clark v. Community for Creative Non-Violence","cite":"468 U.S. 288","y":1984,"id":"1983/82-1998","sc":1,"op":1,"sum":"In a 7-to-2 decision, the Court held that the regulations did not violate the First Amendment. The Court noted that expression is subject to reasonable time, place, and manner restrictions, and that the manner of the protest was at odds with the government's interest in maintaining the condition of the parks.","sumSrc":"Oyez","by":{"2":"26","4":"7"}},{"t":"case","label":"Columbia Broadcasting System, Inc. v. Democratic National Committee","cite":"412 U.S. 94","y":1973,"id":"1972/71-863","sc":1,"op":1,"sum":"Neither the Communications Act nor the First Amendment requires broadcasters to accept paid editorial 'advertisements. Pp. 101-114; 121-170. 146 U. S. App. D. C. 181, 450 F. 2d 642, reversed. MR.CHIEF JusTicE BURGER delivered the opinion.'of the Court with respect to Parts I, II, and IV, finding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Heffron v. International Society for Krishna Consciousness, Inc.","cite":"452 U.S. 640","y":1981,"id":"1980/80-795","sc":1,"ar":1,"sum":"Using the \"valid time, manner, and place\" criteria which the Court employs to assess government restrictions of First Amendment activities, the Court held that Rule 6.05 did not violate the Constitution.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Hernandez v. Mesa","cite":"589 U.S. 93","y":2020,"id":"2019/17-1678","sc":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Kovacs v. Cooper","cite":"336 U.S. 77","y":1949,"id":"1940-1955/336us77","sc":1,"sum":"The court affirmed the New Jersey Court of Errors and Appeals and upheld Kovacs' conviction.","sumSrc":"Oyez","by":{"2":"27","4":"6, 7, 8"}},{"t":"case","label":"Members of City Council v. Taxpayers for Vincent","cite":"466 U.S. 789","y":1984,"id":"1983/82-975","sc":1,"sum":"Section 28.04 of the Los Angeles Municipal Code prohibits the posting of signs on public property. Appellee Taxpayers for Vincent, a group of supporters of a candidate for election to the Los Angeles City Council, entered into a contract with appellee Candidates' Outdoor Graphics Service (COGS) to fabricate and post signs with the candidate's name on them. COGS produced cardboard signs and attached them to utility …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"Moving Phones Partnership v. FCC","cite":"998 F.2d 1051","y":1993,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/998/1051/","by":{"2":"39"}},{"t":"case","label":"Murthy v. Missouri","cite":"603 U.S. 43","y":2024,"id":"2023/23-411","sc":1,"op":1,"sum":"Respondents—two States and five individual social-media users who sued Executive Branch officials and agencies, alleging that the Government pressured the platforms to censor their speech in violation of the First Amendment—lack Article III standing to seek an injunction.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"48","3":"17","4":"17"}},{"t":"case","label":"NRA v. Vullo","cite":"602 U.S. 175","y":2024,"id":"2023/22-842","sc":1,"sum":"The NRA plausibly alleged that respondent violated the First Amendment by coercing regulated entities to terminate their business relationships with the NRA in order to punish or suppress the NRA’s gun-promotion advocacy.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"48"}},{"t":"case","label":"Pacific Networks Corp. v. FCC","cite":"77 F.4th 1160","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/77/1160/","by":{"2":"39"}},{"t":"case","label":"Texas v. Lesage","cite":"528 U.S. 18","y":1999,"id":"1999/98-1111","sc":1,"sum":"In a unanimous per curiam opinion, the Court held that \"[i]nsofar as the Court of Appeals held that [the University of Texas was] not entitled to summary judgment on Lesage's section 1983 claim for damages relating to the rejection of his application for the 1996-1997 academic year even if he would have been denied admission under a race-neutral policy, its decision contradicts our holding in Mt. Healthy.\" \"Under Mt.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"TikTok Inc. v. Trump","cite":"507 F. Supp. 3d 92","y":2020,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/507/92/","op":1,"by":{"2":"7"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Trump v. Mazars USA, LLP","cite":"591 U.S. 848","y":2020,"id":"2019/19-715","sc":1,"sum":"Cases in which the Court held that while the Constitution does not prohibit congressional subpoenas issued to the sitting President, the courts below did not adequately weigh the separation-of-powers concerns raised by the subpoenas in these cases.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"United States v. Stanchich","cite":"550 F.2d 1294","y":1977,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/550/1294/","by":{"2":"27"}},{"t":"case","label":"Virginia v. Hicks","cite":"539 U.S. 113","y":2003,"id":"2002/02-371","sc":1,"sum":"The Court held that the RRHA's trespass policy is not facially invalid under the First Amendment's overbreadth doctrine.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Ward v. Rock Against Racism","cite":"491 U.S. 781","y":1989,"id":"1988/88-226","sc":1,"op":6,"sum":"Holding noise control and sound quality justifcations behind city sound amplifcation guideline were content neutral.","sumSrc":"opinion","by":{"2":"24-26"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35"}},{"t":"usc","label":"50 U.S.C. § 1701","url":"https://www.law.cornell.edu/uscode/text/50/1701","stext":{"head":"§1701. Unusual and extraordinary threat; declaration of national emergency; exercise of Presidential authorities","paras":[[0,"(a) Any authority granted to the President by section 1702 of this title may be exercised to deal with any unusual and extraordinary threat, which has its source in whole or substantial part outside the United States, to the national security, foreign policy, or economy of the United States, if the President declares a national emergency with respect to such threat."],[0,"(b) The authorities granted to the President by section 1702 of this title may only be exercised to deal with an unusual and extraordinary threat with respect to which a national emergency has been declared for purposes of this chapter and may not be exercised for any other purpose. Any exercise of such authorities to deal with any new threat shall be based on a new declaration of national emergency which must be with respect to such threat."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1701. Unusual and extraordinary threat; declaration of national emergency; exercise of Presidential authorities","tname":"War and National Defense","by":{"2":"6"}},{"t":"law","label":"No TikTok on Government Devices Act, Pub. L. No. 117-328","url":"https://www.govinfo.gov/link/plaw/117/public/328","by":{"2":"8"}},{"t":"usc","label":"10 U.S.C. § 4872","url":"https://www.law.cornell.edu/uscode/text/10/4872","subs":["(d)(2)"],"by":{"2":"10"}},{"t":"usc","label":"12 U.S.C. § 72","url":"https://www.law.cornell.edu/uscode/text/12/72","by":{"2":"39"}},{"t":"usc","label":"16 U.S.C. § 797","url":"https://www.law.cornell.edu/uscode/text/16/797","by":{"2":"39"}},{"t":"usc","label":"42 U.S.C. § 2131","url":"https://www.law.cornell.edu/uscode/text/42/2131","by":{"2":"39"}},{"t":"usc","label":"47 U.S.C. § 35","url":"https://www.law.cornell.edu/uscode/text/47/35","by":{"2":"39"}},{"t":"usc","label":"47 U.S.C. § 214","url":"https://www.law.cornell.edu/uscode/text/47/214","by":{"2":"39"}},{"t":"usc","label":"47 U.S.C. § 310","url":"https://www.law.cornell.edu/uscode/text/47/310","subs":["(b)(3)"],"stext":{"head":"§310. License ownership restrictions","paras":[[0,"(a) Grant to or holding by foreign government or representative"],[0,"The station license required under this chapter shall not be granted to or held by any foreign government or the representative thereof."],[0,"(b) Grant to or holding by alien or representative, foreign corporation, etc."],[0,"No broadcast or common carrier or aeronautical en route or aeronautical fixed radio station license shall be granted to or held by—"],[1,"(1) any alien or the representative of any alien;"],[1,"(2) any corporation organized under the laws of any foreign government;"],[1,"(3) any corporation of which more than one-fifth of the capital stock is owned of record or voted by aliens or their representatives or by a foreign government or representative thereof or by any corporation organized under the laws of a foreign country;"],[1,"(4) any corporation directly or indirectly controlled by any other corporation of which more than one-fourth of the capital stock is owned of record or voted by aliens, their representatives, or by a foreign government or representative thereof, or by any corporation organized under the laws of a foreign country, if the Commission finds that the public interest will be served by the refusal or revocation of such license."],[0,"(c) Authorization for aliens licensed by foreign governments; multilateral or bilateral agreement to which United States and foreign country are parties as prerequisite"],[0,"In addition to amateur station licenses which the Commission may issue to aliens pursuant to this chapter, the Commission may issue authorizations, under such conditions and terms as it may prescribe, to permit an alien licensed by his government as an amateur radio operator to operate his amateur radio station licensed by his government in the United States, its possessions, and the Commonwealth of Puerto Rico provided there is in effect a multilateral or bilateral agreement, to which the United States and the alien's government are parties, for such operation on a reciprocal basis by United States amateur radio operators. Other provisions of this chapter and of subchapter II of chapter 5, and chapter 7, of title 5 shall not be applicable to any request or application for or modification, suspension, or cancellation of any such authorization."],[0,"(d) Assignment and transfer of construction permit or station license"],[0,"No construction permit or station license, or any rights thereunder, shall be transferred, assigned, or disposed of in any manner, voluntarily or involuntarily, directly or indirectly, or by transfer of control of any corporation holding such permit or license, to any person except upon application to the Commission and upon finding by the Commission that the public interest, convenience, and necessity will be served thereby. Any such application shall be disposed of as if the proposed transferee or assignee were making application under section 308 of this title for the permit or license in question; but in acting thereon the Commission may not consider whether the public interest, convenience, and necessity might be served by the transfer, assignment, or disposal of the permit or license to a person other than the proposed transferee or assignee."],[0,"(e) Administration of regional concentration rules for broadcast stations"],[0,"(1) In the case of any broadcast station, and any ownership interest therein, which is excluded from the regional concentration rules by reason of the savings provision for existing facilities provided by the First Report and Order adopted March 9, 1977 (docket No. 20548; 42 Fed. Reg. 16145), the exclusion shall not terminate solely by reason of changes made in the technical facilities of the station to improve its service."],[0,"(2) For purposes of this subsection, the term \"regional concentration rules\" means the provisions of sections 73.35, 73.240, and 73.636 of title 47, Code of Federal Regulations (as in effect June 1, 1983), which prohibit any party from directly or indirectly owning, operating, or controlling three broadcast stations in one or several services where any two of such stations are within 100 miles of the third (measured city-to-city), and where there is a primary service contour overlap of any of the stations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/310?type=usc&year=mostrecent&link-type=html"},"head":"§310. License ownership restrictions","tname":"Telecommunications","by":{"2":"39","4":"15"}},{"t":"usc","label":"49 U.S.C. § 40102","url":"https://www.law.cornell.edu/uscode/text/49/40102","subs":["(a)(15)"],"by":{"2":"39"}},{"t":"usc","label":"49 U.S.C. § 41102","url":"https://www.law.cornell.edu/uscode/text/49/41102","subs":["(a)"],"by":{"2":"39"}},{"t":"usc","label":"50 U.S.C. § 4565","url":"https://www.law.cornell.edu/uscode/text/50/4565","subs":["(a)(B)"],"stext":{"head":"§4565. Authority to review certain mergers, acquisitions, and takeovers","paras":[[0,"(a) Definitions"],[0,"In this section:"],[0,"(1) Clarification"],[1,"The term \"national security\" shall be construed so as to include those issues relating to \"homeland security\", including its application to critical infrastructure."],[0,"(2) Committee; chairperson"],[1,"The terms \"Committee\" and \"chairperson\" mean the Committee on Foreign Investment in the United States and the chairperson thereof, respectively."],[0,"(3) Control"],[1,"The term \"control\" means the power, direct or indirect, whether exercised or not exercised, to determine, direct, or decide important matters affecting an entity, subject to regulations prescribed by the Committee."],[0,"(4) Covered transaction"],[0,"(A) In general"],[2,"Except as otherwise provided, the term \"covered transaction\" means—"],[3,"(i) any transaction described in subparagraph (B)(i); and"],[3,"(ii) any transaction described in clauses (ii) through (v) of subparagraph (B) that is proposed, pending, or completed on or after the effective date set forth in section 1727 of the Foreign Investment Risk Review Modernization Act of 2018."],[0,"(B) Transactions described"],[2,"A transaction described in this subparagraph is any of the following:"],[3,"(i) Any merger, acquisition, or takeover that is proposed or pending after August 23, 1988, by or with any foreign person that could result in foreign control of any United States business, including such a merger, acquisition, or takeover carried out through a joint venture."],[3,"(ii) Subject to subparagraphs (C) and (E), the purchase or lease by, or a concession to, a foreign person of private or public real estate that—"],[4,"(I) is located in the United States;"],[4,"(II)(aa) is, is located within, or will function as part of, an air or maritime port; or"],[4,"(bb)(AA) is in close proximity to a United States military installation or another facility or property of the United States Government that is sensitive for reasons relating to national security;"],[4,"(BB) could reasonably provide the foreign person the ability to collect intelligence on activities being conducted at such an installation, facility, or property; or"],[4,"(CC) could otherwise expose national security activities at such an installation, facility, or property to the risk of foreign surveillance; and"],[4,"(III) meets such other criteria as the Committee prescribes by regulation, except that such criteria may not expand the categories of real estate to which this clause applies beyond the categories described in subclause (II)."],[3,"(iii) Any other investment, subject to regulations prescribed under subparagraphs (D) and (E), by a foreign person in any unaffiliated United States business that—"],[4,"(I) owns, operates, manufactures, supplies, or services critical infrastructure;"],[4,"(II) produces, designs, tests, manufactures, fabricates, or develops one or more critical technologies; or"],[4,"(III) maintains or collects sensitive personal data of United States citizens that may be exploited in a manner that threatens national security."],[3,"(iv) Any change in the rights that a foreign person has with respect to a United States business in which the foreign person has an investment, if that change could result in—"],[4,"(I) foreign control of the United States business; or"],[4,"(II) an investment described in clause (iii)."],[3,"(v) Any other transaction, transfer, agreement, or arrangement, the structure of which is designed or intended to evade or circumvent the application of this section, subject to regulations prescribed by the Committee."],[0,"(C) Real estate transactions"],[0,"(i) Exception for certain real estate transactions"],[3,"A real estate purchase, lease, or concession described in subparagraph (B)(ii) does not include a purchase, lease, or concession of—"],[4,"(I) a single \"housing unit\", as defined by the Census Bureau; or"],[4,"(II) real estate in \"urbanized areas\", as defined by the Census Bureau in the most recent census, except as otherwise prescribed by the Committee in regulations in consultation with the Secretary of Defense."],[0,"(ii) Definition of close proximity"],[3,"With respect to a real estate purchase, lease, or concession described in subparagraph (B)(ii)(II)(bb)(AA), the Committee shall prescribe regulations to ensure that the term \"close proximity\" refers only to a distance or distances within which the purchase, lease, or concession of real estate could pose a national security risk in connection with a United States military installation or another facility or property of the United States Government described in that subparagraph."],[0,"(D) Other investments"],[0,"(i) Other investment defined"],[3,"For purposes of subparagraph (B)(iii), the term \"other investment\" means an investment, direct or indirect, by a foreign person in a United States business described in that subparagraph that is not an investment described in subparagraph (B)(i) and that affords the foreign person—"],[4,"(I) access to any material nonpublic technical information in the possession of the United States business;"],[4,"(II) membership or observer rights on the board of directors or equivalent governing body of the United States business or the right to nominate an individual to a position on the board of directors or equivalent governing body; or"],[4,"(III) any involvement, other than through voting of shares, in substantive decisionmaking of the United States business regarding—"],[5,"(aa) the use, development, acquisition, safekeeping, or release of sensitive personal data of United States citizens maintained or collected by the United States business;"],[5,"(bb) the use, development acquisition, or release of critical technologies; or"],[5,"(cc) the management, operation, manufacture, or supply of critical infrastructure."],[0,"(ii) Material nonpublic technical information defined"],[0,"(I) In general"],[4,"For purposes of clause (i)(I), and subject to regulations prescribed by the Committee, the term \"material nonpublic technical information\" means information that—"],[5,"(aa) provides knowledge, know-how, or understanding, not available in the public domain, of the design, location, or operation of critical infrastructure; or"],[5,"(bb) is not available in the public domain, and is necessary to design, fabricate, develop, test, produce, or manufacture critical technologies, including processes, techniques, or methods."],[0,"(II) Exemption for financial information"],[4,"Notwithstanding subclause (I), for purposes of this subparagraph, the term \"material nonpublic technical information\" does not include financial information regarding the performance of a United States business."],[0,"(iii) Regulations"],[0,"(I) In general"],[4,"The Committee shall prescribe regulations providing guidance on the types of transactions that the Committee considers to be \"other investment\" for purposes of subparagraph (B)(iii)."],[0,"(II) United States businesses that own, operate, manufacture, supply, or service critical infrastructure"],[4,"The regulations prescribed by the Committee with respect to an investment described in subparagraph (B)(iii)(I) shall—"],[5,"(aa) specify the critical infrastructure subject to that subparagraph based on criteria intended to limit application of that subparagraph to the subset of critical infrastructure that is likely to be of importance to the national security of the United States; and"],[5,"(bb) enumerate specific types and examples of such critical infrastructure."],[0,"(iv) Specific clarification for investment funds"],[0,"(I) Treatment of certain investment fund investments"],[4,"Notwithstanding clause (i)(II) and subject to regulations prescribed by the Committee, an indirect investment by a foreign person in a United States business described in subparagraph (B)(iii) through an investment fund that affords the foreign person (or a designee of the foreign person) membership as a limited partner or equivalent on an advisory board or a committee of the fund shall not be considered an \"other investment\" for purposes of subparagraph (B)(iii) if—"],[5,"(aa) the fund is managed exclusively by a general partner, a managing member, or an equivalent;"],[5,"(bb) the general partner, managing member, or equivalent is not a foreign person;"],[5,"(cc) the advisory board or committee does not have the ability to approve, disapprove, or otherwise control—"],[6,"(AA) investment decisions of the fund; or"],[6,"(BB) decisions made by the general partner, managing member, or equivalent related to entities in which the fund is invested;"],[5,"(dd) the foreign person does not otherwise have the ability to control the fund, including the authority—"],[6,"(AA) to approve, disapprove, or otherwise control investment decisions of the fund;"],[6,"(BB) to approve, disapprove, or otherwise control decisions made by the general partner, managing member, or equivalent related to entities in which the fund is invested; or"],[6,"(CC) to unilaterally dismiss, prevent the dismissal of, select, or determine the compensation of the general partner, managing member, or equivalent;"],[5,"(ee) the foreign person does not have access to material nonpublic technical information as a result of its participation on the advisory board or committee; and"],[5,"(ff) the investment otherwise meets the requirements of this subparagraph."],[0,"(II) Treatment of certain waivers"],[0,"(aa) In general"],[5,"For the purposes of items (cc) and (dd) of subclause (I) and except as provided in item (bb), a waiver of a potential conflict of interest, a waiver of an allocation limitation, or a similar activity, applicable to a transaction pursuant to the terms of an agreement governing an investment fund shall not be considered to constitute control of investment decisions of the fund or decisions relating to entities in which the fund is invested."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/4565?type=usc&year=mostrecent&link-type=html"},"head":"§4565. Authority to review certain mergers, acquisitions, and takeovers","tname":"War and National Defense","by":{"2":"39","4":"14"}},{"t":"reg","label":"Exec. Order No. 13,942, 85 Fed. Reg. 48,637","url":"https://www.govinfo.gov/link/fr/85/48637","by":{"2":"5, 6, 31"}},{"t":"reg","label":"Exec. Order No. 14,034, 86 Fed. Reg. 31,423","url":"https://www.govinfo.gov/link/fr/86/31423","by":{"2":"7"}},{"t":"reg","label":"85 Fed. Reg. 51,297","url":"https://www.govinfo.gov/link/fr/85/51297","by":{"2":"7"}},{"t":"case","label":"Billups v. City of Charleston","cite":"961 F.3d 673","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/961/673/","by":{"3":"14"}},{"t":"case","label":"Bluman v. FEC","cite":"800 F. Supp. 2d 281","y":2011,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/800/281/","by":{"3":"8"}},{"t":"case","label":"Bluman v. FEC","cite":"565 U.S. 1104","y":2012,"url":"https://supreme.justia.com/cases/federal/us/565/1104/","sc":1,"by":{"3":"8"}},{"t":"case","label":"Dep’t of Com. v. New York","cite":"588 U.S. 752","y":2019,"url":"https://supreme.justia.com/cases/federal/us/588/752/","sc":1,"by":{"3":"24"}},{"t":"case","label":"Free Speech Coalition, Inc. v. Paxton","cite":"95 F.4th 263","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/95/263/","by":{"3":"7, 8"}},{"t":"case","label":"Hunter v. Underwood","cite":"471 U.S. 222","y":1985,"id":"1984/84-76","sc":1,"ar":5,"sum":"Section 182 violates the Equal Protection Clause of the Fourteenth Amendment. Arlington Heights v. MetropolitanHousingDevelopment Corp., 429 U. S. 252. That § 182 may have been adopted to discriminate against poor whites as well as against blacks would not render nugatory the purpose to discriminate against blacks, it being clear that the latter was a \"but-for\" motivation for adopting § 182. There is no evidence …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18, 19","4":"19"}},{"t":"case","label":"Manhattan Cmty. Access Corp. v. Halleck","cite":"587 U.S. 802","y":2019,"id":"2018/17-1702","sc":1,"sum":"The Court held that Manhattan Community Access Corp, which operates public access channels, is not a state actor subject to constitutional liability.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"Riley v. Nat’l Fed’n of Blind of N.C., Inc.","cite":"487 U.S. 781","y":1988,"id":"1987/87-328","sc":1,"ar":1,"sum":"The North Carolina Charitable Solicitations Act defines the prima facie \"reasonable fee\" that a professional fundraiser may charge according to a three-tiered schedule. A fee up to 20% of receipts collected is deemed reasonable. A fee between 20% and 35% is deemed unreasonable upon a showing that the solicitation at issue did not involve the \"dissemination of information, discussion, or advocacy relating to public …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"Thunder Studios, Inc. v. Kazal","cite":"13 F.4th 736","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/13/736/","by":{"3":"8"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"reg","label":"17 C.F.R. § 229.106","url":"https://www.ecfr.gov/current/title-17/section-229.106","by":{"3":"14"}},{"t":"case","label":"Bridges v. Wixon","cite":"326 U.S. 135","y":1945,"id":"scdb/1944-064","sc":1,"by":{"4":"13"}},{"t":"case","label":"Church of Lukumi Babalu Aye, Inc. v. City of Hialeah","cite":"508 U.S. 520","y":1993,"id":"1992/91-948","sc":1,"sum":"The Court found that an ordinance banning religious animal sacrifice was unconstitutional under the Free Exercise Clause of the First Amendment.","sumSrc":"Oyez","by":{"4":"19"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"4":"23"}},{"t":"case","label":"Greene v. McElroy","cite":"360 U.S. 474","y":1959,"id":"1958/180","sc":1,"op":2,"sum":"In the absence of explicit authorization from either the President or Congress, the Secretaries of the Armed Forces were not authorized to deprive petitioner of his job in a proceeding in which he was not afforded the safeguards of confrontation and cross-examination.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"23"}},{"t":"case","label":"Kaley v. United States","cite":"571 U.S. 320","y":2014,"id":"2013/12-464","sc":1,"sum":"The Court held that the Fifth and Sixth Amendments do not allow an individual to use funds obtained illegally to pay for an attorney.","sumSrc":"Oyez","by":{"4":"23"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"4":"20"}},{"t":"usc","label":"15 U.S.C. § 45","url":"https://www.law.cornell.edu/uscode/text/15/45","subs":["(m)"],"by":{"4":"22"}},{"t":"usc","label":"15 U.S.C. § 57a","url":"https://www.law.cornell.edu/uscode/text/15/57a","by":{"4":"22"}},{"t":"usc","label":"22 U.S.C. § 612","url":"https://www.law.cornell.edu/uscode/text/22/612","by":{"4":"16"}}]};